        content: `I AM CURRENTLY stalking my crush's timeline habang nasa sala ako nang biglang magulat ako dahil ginulat ako ni Ate.

"Pati diyan sa laptop mo, ini-stalk mo 'yung crush mo ha! Ikaw ha!"

Napasara naman ako sa laptop ko and tinignan ko si Ate. "Hanggang stalk na nga lang at saka isa pa, muntik na akong mahimatay sa gulat mo."

"Kanina pa kita tinitignan, sis tapos nakangiti ka pa na parang tanga lang! Nako, kakanood mo siguro 'yan ng BL series kaya pati habang gising ka iniisip mo ang crush mo. Magtapat ka na, baka mapatulan ka!"

"Wala 'to, ano ka ba! Nakapaka-tsismosa mo talaga at saka straight 'to kaya hindi ako papatulan nito. Sa BL series lang 'yon nangyayari," naiinis kong sabi kay Ate pero tumatawa lang siya.

"Ayaw mo no'n? May thrill?"

"Baka sa kakanood mo rin 'yan ng twitter, Dale," singit ni Kuya na ikinalingon namin. Aakyat siya ng hagdan. "Kaya pinagpapatansyahan din niya 'yung crush niyang straight," dagdag pa ni Kuya sabay akyat na sa taas habang tumatawa.

"Grabe na kayo! Mga kapatid ko ba talaga kayo?! Kay Brylle lang naman ako nababading!"

Umalis si Ate sa harap ko na natatawa pa nga sa akin. Napa-hmp tuloy ako at binuksan ko na lang muli 'yung laptop ko tapos tinignan ko na lang 'yung naka-only me niyang profile picture.

Napaisip ako tuloy... Hanggang pangarap na lang ba talaga ako sa 'yo, Brylle?

..

NOW, I'm here at school tapos nasa harap ko pa si crush at nasa likod niya ako. Ito ang sitting arrangement kasi namin. My gosh! Kahit likod niya ang guwapo! Tangkad din nito at fit ang pangangatawan na medyo moreno.

Exam pala namin ngayong week. Hindi ko na naisip kahit college na ako at nawala na rin sa isip ko na mahirap ang mga 'yon because of my crush, he's my inspiration and I hope na kayo rin may inspirasyon.

"TARA, bar!"

Aya bigla nung kaklase ko na friend ko after our class. 7 PM pa naman ang tapos ng exam namin kasi nakasabay sa schedule ng subject namin.

"Sige na, hanggang 9 PM lang, promise!" pagpipilit pa ni Celine.

"Sino'ng kasama?" tanong ko.

"Si Xandra at Rica tapos si baklang Dominador." Natawa pa siya sa huli niyang sinabi.

Natawa rin ako dahil kay Dominador. "Gago! Domina dapat ang tawag natin do'n, marinig ka at malalagot ka! Anyways, saan tayo magkikita?"

"Doon na mismo!" sagot niya habang tumatawa.

Taga ibang section kasi ang tropa namin tapos si Rica at Domina ay iba ang grade level. 2nd year kami nila Celine at Xandra habang sila Domina ay 1st year.

MADALI naman kami nakarating ng Bar dahil sa hindi naman uniform ang suot namin. Doon nga ay sinalubong na nga kami nung Tatlo at nang nandito na kami sa table raw namin ay pina-shot na ako bigla ni Domina.

"Sige na, bakla! Shot puno na!"

"Tangina ang dami nito, Domina!" natatawa kong sabi sabay kuha nung malaking shot glass na may punong-puno na alak. "Isa lang, ha," pakondisyon ko.

"Sige, sige," aniya.

Ito ang maganda sa friendship namin, hindi pinipilit ang may ayaw. Pinagbibigyan ko naman sila eh kaya nga kahit isang shot lang ay pumapayag ako. Nung pagkalagok ko ng alak ay nag-cheer pa nga sila.

"Nice, manginginom na siya official!" asar ni Xandra sa 'kin.

"Nilagok ni bakla, oh heto! Lemon, chaser," abot naman ni Rica sa 'kin sa lemon na agad ko namang kinuha. Sobrang pait kasi nung alak, hard pa!

"Pait gago! Pa'no kayo nakakainom nang marami? My gosh!" sabi ko habang napapangiwi dahil sa pait.

"Tanga ka kasi bakla, hindi ka kaagad umano ng chaser natin," na-tanga pa nga ako ni Domina.

"Shutabels naman kasi, late naman kasi binigay ni Rica!" pakikipagtalo ko pa pero natawa na lang sila.

Makailang sandali ay biglang nakarinig ako ng "woohoo" sa may bandang gitna at nakita ko ang kumpulan ng mga tao roon. Kinabog ako bigla roon nang hindi ko alam sa pakiramdam ko lalo pa nung napagdesisyunan na maki-tsismis ng mga kasama ko roon. Subalit nang pagkapunta namin dito ay laking gulat ko na si Brylle pala 'yung pinagkakatuwaan nilang sumasayaw.

"Fatay! Crush mo, bebs!" bulong sa 'kin ni Celine.

Hindi ko na pinansin si Celine bagkus ay lumapit kaagad ako kay Brylle para patigilin siya, nakakainis kasi pinagkakatuwaan siya porket lasing!

"Si Brylle. Kaklase namin 'yan ni Dale," rinig ko'ng pagsagot ni Celine sa mga kasama ko nung nagtanong sila kung bakit ko nilapitan si Brylle.

"Una na 'ko, guys," paalam ko sa mga kaibigan ko saka na 'ko naglakad habang inaalalayan si Brylle na lasing.

"Ingat kayo! OMG!" dinig ko pang sinabi ni Celine.

"Dale, is that you?" lasing na tanong ni Brylle sa 'kin. Papikit-pikit siyang nakatingin sa 'kin.

"Oo, ako 'to, ihahatid kita sa inyo," sabi ko at nandito na kami ngayon sa gilid ng kalsada, nag-aabang ako ng taxi.

"Sus, kaya mo lang ginagawa ito kasi crush mo 'ko! Hahaha!"

Napalingon ako sa lasing niyang pagkakasabi no'n. Nagulat ako dahil alam niyang crush ko siya?

"Matagal ko nang alam, Dale," dagdag niya. "Cute mo, p're!" biglang sabi niya tapos natawa.

Hindi ko na lamang siya pinansin bagkus itinuon ko na lang ang pag-aabang ng taxi hanggang sa may tumigil na nga sa harap namin.

Una ko siyang ipinasok sa loob bago rin ako pumasok. Pagkaandar naman ng taxi ay nagulat ako nung sumandal siya sa 'kin at yumakap.

"Alam mo ba kung bakit ako uminom?" tanong niya na natatawa. "Hulaan mo!"

"Brylle, lasing ka na!"

"Hindi ako lasheng! Hulaan mo nga!"

"Ano?" pagpatol ko na lang sa kalasingan niya.

"Kasi wala akong masagot sa exam," natatawang sabi niya. "Pero umasa na lang ako sa stock knowledge ko pero ang kaso ay hindi ako sure sa mga sagot ko."

"Ay ganoon ba," nasagot ko na lang.

"Oo, wala kasi akong masyadong friend eh at wala pa 'kong jowa na dadamayan pero may crush din ako, isa lang."

Lalo pa siyang yumakap sa 'kin. Hindi ko nga alam pero parang nakakakiliti sa kaloob-looban ko dahil sa skin touch niya rin sa 'kin. Ganito pala feeling, ano? Kapag 'yung crush mo ganito.

Nailang pa nga ako bigla nung kaniya akong tignan.

Lalo pa nung walang pasubali niya akong hinalikan. Akala ko smack lang pero humaba pa ito nang ilang segundo kaya hindi ko namamalayang tumugon na rin ako sa kaniyang halik.

Matapos ang ilang saglit ay siya na ang mismong bumitiw at tila nawala ang pagkalasing niya nung iwasan niya ako ng tingin.

"Sorry, Dale, I thought you're a girl."

Biglang parang may kumirot sa puso ko sa sinabi niya. "Ah, sorry rin."

Umiwas siya ng tingin sa akin at itinuon niya ang pagtingin niya sa bintana. Nasa magkabilang dulo na nga kaming dalawa na kanina lang ay magkadikit na magkadikit.

"Manong dito na po ako," sabi ni Brylle at kaagad naman tumigil 'yung taxi. "Heto, Dale, para sa pamasahe mo. Salamat," aniya sabay nag-abot siya ng 100 pesos sa 'kin.

Nang isara niya na ang pinto ng taxi kasi aalis na siya ay napahawak ako bigla sa labi ko. Mabuti na lang na hindi kami nakita ng Driver dahil madilim dito sa taxi.

Basta ang nararamdaman ko ngayon... Kilig at sakit.

AFTER that happened ay nagbago ang lahat. Hindi ko nga makalimutan 'yon eh, ang kaso nga lamang ay pansin kong iniiwasan niya ako at ako nga rin ay ganoon, nakakailang kasi. So that's a reason why I felt heartache too.

Last day na ng exam namin at magse-semestral break na... Ang tagal ko muli siyang hindi masisilayan, maybe two weeks. Kung sa iba ay saglit lang 'yon pero sa akin ay ang tagal-tagal! Hanggang stalk na lang ako sa kaniya no'n pag nagkataon.

Nagkatotoo nga 'yung sinabi ko dahil sa panahon ng semestral break ay pakiramdam ko'y miss na miss ko siya. Palagi kong sino-stalk ang timeline niyang walang masyadong post at binabasa ko palagi 'yung convo namin na kakarampot lamang na tanungan lang ang tanging laman. Ang matindi pa nito ay napapaginipan ko pa siya at madalas na panaginip ko ay 'yung nangyari sa taxi.

..

SECOND semester na nga at back to class na, enrolled na ako pero ang problema ko na lang ay 'yung heto.. Nakikita ko na naman si Brylle. Nilampasan niya nga lang ako.

Ganoon na nga ang nangyayari kaya hinayaan ko na lang. Break time na nga no'n at nakita ko siya na bumibili ng snacks. Subalit inalis ko na lang ang tingin ko sa kaniya nung nakaramdam ako ng pagkaihi.

"Ihi muna 'ko, Celine ah," paalam ko kila Celine bago ako umalis sa harapan nila.

Nung pagkapunta ko sa CR ay kaagad akong umihi subalit nung pagkatapos kong umihi ay aalis na sana ako nang biglang may nasagi ako.

"Fuck!"

Napatingin ako bigla kay Brylle na siyang nasanggi ko and I realized na natapon 'yung hawak-hawak niyang bottled water sa suot niya.

"Sorry, Brylle."

"What's your problem, huh? Palagi ka na lang!"

Sandali ko pa siyang tinignan. Galit siya. Ang sakit nito sa damdamin ko.

"Aalis na lang ako."

"Wait," hinawakan ni Brylle ang braso ko. "Puwede ba kitang makausap?"

"Huh?" Naisagot ko na lang dahil hindi ko alam ang isasagot ko.

Nagpunta si Brylle sa door at nakita kong sumilip-silip siya sa labas. Napalunok na lamang ako nang bigla niyang isinara ang pinto.

"Dale," tawag niya sa pangalan ko at saka niya ako nilapitan.

"Brylle, ano'ng gagawin mo?"

Nagulat na lamang ako when he suddenly kissed my lips. Napatugon ako bigla roon at sa sandaling 'yon ay nawala ang pangungulila ko kay Brylle. Naramdaman ko muli ang halik niya noong nasa taxi kami noon.

Nang bitiwan niya ang halik niya sa akin ay nagkatinginan kami sa isa't isa.

"Damn it," mura niya. "Bakit ganito pa rin 'yung feeling?!"

"Brylle, a-ano'ng sinasabi mo na feeling?" nauutal kong tanong.

"No, this is can't be happen. Straight ako but I don't understand why I like you!"

Parang nagtambol ang mga kalamnan ko dahil hindi ko maintindihan ang mararamdaman ko. Sasaya ba, kikiligin o magtataka ba sa sinasabi niya like ewan!

"I kissed you, Dale because I want to see if that's still same."

"Same ang alin, Brylle?"

"'Yung feelings ko," hinawakan niya ako bigla sa magkabilang mukha ko. "'Yung feelings ko when we're kissed last time sa taxi but I don't care, Dale!" Tumigil siya saglit sa kaniyang pagsasalita. "But may I kiss you again?"

Kusa na lang akong tumango sa favor niya kaya walang pasubali niya akong hinalikan at mas mahaba na nga iyon kaysa sa kanina at nung sa taxi.

Ewan ko that day, nakailang halikan yata kami sa CR at confessions no'n sa isa't isa hanggang sa matapos ang break time. Mabuti na lang at walang kumantok noon tapos kami lang dalawa sa CR noon. Mabuti na lang!

..

MATAPOS niyan, nagkapalagayan na nga kami ng loob ni Brylle. He treated me like a girl and after many months ay naging kami na ni Brylle. Masaya kami ni Brylle kahit na pasikreto 'yon kaso nung malaman na nga ng lahat ay roon nagkaroon ng problema. Noong una ay tinitiis ko pero ngayon, hindi na.

"Bry, bakit ka naman natatakot, huh? Na i-judge tayo ng mga tao, ganoon ba?!" Hindi ko na napigilan ang pag-burst ko sa kaniya.

"OO!" sigaw niya sa 'kin at nagsibagsakan naman ang mga luha ko. "Aaminin ko sa 'yo, Dale. Hinahanap ko pa rin 'yung pakiramdam ng sa babae. Napapaisip nga 'ko dahil straight ako at sa 'yo lang ako ganito... Nababading lang ako sa 'yo, Dale. Nababading lang!"

Hindi ko napigilan na sampalin siya dahil sa sinabi niya. "Nababading lang?!"

"Dale, that's not what I mean. I mean, I do not like guys but only you, ikaw lang ang nakapagparamdam sa 'kin ng ganito," aniya habang inaamo ako.

"Ano ba kasi 'yon?! Na straight ka? Tapos BAKLA lang ako? Sige, ipangalandakan mo pa na bakla ako at lalaki ka! Sige, isigaw mo pa sa lahat! Iparinig mo!" humagulgol na nga 'ko habang sinasabi ko 'yan.

"Sorry, Dale," lumapit siya sa 'kin at pinunasan ang luha sa mata ko gamit ang kaniyang palad. "Iniisip ko lang naman 'yan pero hindi ko kayang mawala ka sa buhay ko. Tinamaan na 'ko sa 'yo eh. Tinamaan na ako... Wala eh, mahal na mahal kita eh," nakita ko ang pagluha niya. "At wala na akong pakialam kahit na lalaki tayo pareho. Kahit na bading pa ang itawag sa atin ng lahat basta mahal kita."

"Nasasaktan lang naman kasi ako sa sinasabi mo, Brylle. Sa nababading ka sa 'kin."

"Araw-araw akong bading sa 'yo. Sinasabi ko na 'yan noon pa, 'di ba? Kilig na kilig ka nga eh. Eh bakit ngayon nasasaktan ka na?"

Kaagad akong yumakap sa kaniya at umiyak ako sa chest niya. "Akala ko, iiwan mo 'ko. Akala ko, hindi mo na 'ko love," kawawa kong sabi.

"Akala mo lang 'yon, ano!" Iniharap niya ang mukha ko sa kaniya and suddenly he kissed my lips torridly...

Kahit pa ramdam kong maraming tao na ang nakatingin sa amin. Nandito lang kasi kami sa labas ng university eh kaya kitang-kita kami ng karamihan and for sure narinig nila ang sandaling pagtatalo namin ni Brylle.

So because he kissed me in front of many people, it only proved that he truly loves me at patunay rin na totoo ang mga sinabi niya sa 'kin.

"Sa 'yo rin, Brylle. Wala nang iba. Sa 'yo lang ako nababading," natatawa kong sabi sabay yakap ko muli sa kaniya.

-THE END-`
